import{_ as e,a as n,c as r,ac as t}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"字符串处理","description":"按词组归类、公共前缀、模式查找和频率编码定位字符串算法；匹配前先确认字节下标、Unicode 字符与哈希碰撞的处理方式。","frontmatter":{"title":"字符串处理","description":"按词组归类、公共前缀、模式查找和频率编码定位字符串算法；匹配前先确认字节下标、Unicode 字符与哈希碰撞的处理方式。","generated":"consolidation-v2","showdocs":{"topics":[{"id":"algorithms","title":"算法","link":"/topics/algorithms/"},{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"问题与数据结构","scope":"general","audience":"general","group":"原理与设计","summary":"按词组归类、公共前缀、模式查找和频率编码定位字符串算法；匹配前先确认字节下标、Unicode 字符与哈希碰撞的处理方式。","status":"active","related":[{"title":"Go 算法与容器实践：遍历、排序、递推与堆","link":"/principles/algorithms/exercises/go-interview-algorithm","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组","link":"/principles/algorithms/exercises/leetcode-arrary","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组 · 两数之和至移除元素","link":"/principles/algorithms/exercises/leetcode-arrary-part-01","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组 · 搜索插入位置至完整入口与预期结果","link":"/principles/algorithms/exercises/leetcode-arrary-part-02","kind":"算法推演","scope":"general","audience":"general"},{"title":"0/1 背包","link":"/principles/algorithms/dp/knapsack-01","kind":"问题与数据结构","scope":"general","audience":"general"}],"prev":{"text":"朴素字符串匹配","link":"/principles/algorithms/strings/naive-string-match"},"next":{"text":"最长公共前缀","link":"/principles/algorithms/strings/longest-common-prefix"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"朴素字符串匹配","link":"/principles/algorithms/strings/naive-string-match"},"next":{"text":"最长公共前缀","link":"/principles/algorithms/strings/longest-common-prefix"}},"headers":[],"relativePath":"principles/algorithms/strings/algorithms-strings-general-general.md","filePath":"principles/algorithms/strings/algorithms-strings-general-general.md"}'),i={name:"principles/algorithms/strings/algorithms-strings-general-general.md"};function s(p,a,o,l,d,c){return n(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="字符串处理" tabindex="-1">字符串处理 <a class="header-anchor" href="#字符串处理" aria-label="Permalink to &quot;字符串处理&quot;">​</a></h1><p>本页按场景选择方法；通过各条目链接阅读完整推演、源码和输出。</p><p>先理解 string 的字节下标与 rune；每个 package main 代码块是独立 main.go，不能合并同目录。可在新模块中单独保存一个例子（Go 1.22+，滚动哈希需 64 位 int）。下文输出均为静态推导，本轮未运行；空模式在三种查找中返回 0，未找到返回 -1。</p><table tabindex="0"><thead><tr><th>要解决的问题</th><th>可选方法</th><th>选择前确认</th></tr></thead><tbody><tr><td>归类由相同字符组成的词或提取共同开头</td><td><a href="#entry-anagram-grouping-d39748c208">变位词分组</a>或<a href="#entry-longest-common-prefix-bc1c526919">最长公共前缀</a></td><td>两例都用 rune；分组排序键与跨单词比较前缀是不同任务。</td></tr><tr><td>短文本中查找一个模式</td><td><a href="#entry-naive-string-match-86df383332">朴素字符串匹配</a></td><td>无需预处理，最坏 O(nm)；示例返回 UTF-8 字节下标。</td></tr><tr><td>避免重复前缀导致反复比较</td><td><a href="#entry-kmp-643ba3db31">KMP</a></td><td>前缀函数跳过已知匹配，时间 O(n+m)；示例使用字节下标。</td></tr><tr><td>需要每个位置与整串前缀的匹配长度</td><td><a href="#entry-z-algorithm-a1244b2930">Z 算法</a></td><td>时间 O(n)；拼接模式、分隔符和文本也可查找匹配。</td></tr><tr><td>滑动比较定长窗口</td><td><a href="#entry-rolling-hash-6f96b58019">滚动哈希</a>与<a href="#entry-rabin-karp-38b7a1c919">Rabin–Karp</a></td><td>哈希相同不代表原文相同；Rabin–Karp 会二次比对，最坏性能仍可能退化。</td></tr><tr><td>按符号频率降低加权路径代价</td><td><a href="#entry-huffman-coding-15f81be490">哈夫曼编码</a></td><td>示例只计算总代价；生成实际 0/1 编码还需保存树结构。</td></tr></tbody></table><h2 id="scene-group-and-prefix" tabindex="-1">按字符组成分组与提取公共前缀 <a class="header-anchor" href="#scene-group-and-prefix" aria-label="Permalink to &quot;按字符组成分组与提取公共前缀 {#scene-group-and-prefix}&quot;">​</a></h2><h3 id="entry-anagram-grouping-d39748c208" tabindex="-1">变位词分组 <a class="header-anchor" href="#entry-anagram-grouping-d39748c208" aria-label="Permalink to &quot;变位词分组 {#entry-anagram-grouping-d39748c208}&quot;">​</a></h3><p><span id="输出"></span><span id="示例"></span></p><p><span id="entry-anagram-grouping-d39748c208-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/strings/anagram-grouping">变位词分组</a>。</p><p>排序每个长度为 m 的词需要 O(m log m)；固定小字符集也可用计数向量作键。</p><h3 id="entry-longest-common-prefix-bc1c526919" tabindex="-1">最长公共前缀 <a class="header-anchor" href="#entry-longest-common-prefix-bc1c526919" aria-label="Permalink to &quot;最长公共前缀 {#entry-longest-common-prefix-bc1c526919}&quot;">​</a></h3><p><span id="输出-1"></span><span id="示例-1"></span></p><p><span id="entry-longest-common-prefix-bc1c526919-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/strings/longest-common-prefix">最长公共前缀</a>。</p><p>示例按 rune 比较，不会把中文字符截成无效的 UTF-8 字节片段。</p><h2 id="scene-match-patterns" tabindex="-1">从逐项比对到复用前缀匹配结果 <a class="header-anchor" href="#scene-match-patterns" aria-label="Permalink to &quot;从逐项比对到复用前缀匹配结果 {#scene-match-patterns}&quot;">​</a></h2><h3 id="entry-naive-string-match-86df383332" tabindex="-1">朴素字符串匹配 <a class="header-anchor" href="#entry-naive-string-match-86df383332" aria-label="Permalink to &quot;朴素字符串匹配 {#entry-naive-string-match-86df383332}&quot;">​</a></h3><p><span id="输出-2"></span><span id="示例-2"></span></p><p><span id="entry-naive-string-match-86df383332-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/strings/naive-string-match">朴素字符串匹配</a>。</p><p>这个 Go 例子按 UTF-8 字节查找并返回字节下标。</p><h3 id="entry-kmp-643ba3db31" tabindex="-1">KMP 字符串匹配 <a class="header-anchor" href="#entry-kmp-643ba3db31" aria-label="Permalink to &quot;KMP 字符串匹配 {#entry-kmp-643ba3db31}&quot;">​</a></h3><p><span id="输出-3"></span><span id="示例-3"></span></p><p><span id="entry-kmp-643ba3db31-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/strings/kmp">KMP 字符串匹配</a>。</p><p>本例 KMP 按 UTF-8 字节匹配，因此中文也必须比较每个续字节，不能用 range string 跳过它们。pattern 是模式串；KMP(&quot;你好Go&quot;, &quot;Go&quot;) 返回字节下标 6，查找“好”返回 3，均不表示第几个 rune。空模式返回 0，没有匹配返回 -1。</p><p>预处理和搜索各为线性时间；示例返回字节下标。</p><h3 id="entry-z-algorithm-a1244b2930" tabindex="-1">Z 算法 <a class="header-anchor" href="#entry-z-algorithm-a1244b2930" aria-label="Permalink to &quot;Z 算法 {#entry-z-algorithm-a1244b2930}&quot;">​</a></h3><p><span id="输出-4"></span><span id="示例-4"></span></p><p><span id="entry-z-algorithm-a1244b2930-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/strings/z-algorithm">Z 算法</a>。</p><p>把“模式＋分隔符＋文本”拼接后，也能用 Z 值寻找所有匹配位置。</p><h2 id="scene-hash-moving-windows" tabindex="-1">用滚动哈希筛选窗口并核对匹配 <a class="header-anchor" href="#scene-hash-moving-windows" aria-label="Permalink to &quot;用滚动哈希筛选窗口并核对匹配 {#scene-hash-moving-windows}&quot;">​</a></h2><h3 id="entry-rolling-hash-6f96b58019" tabindex="-1">滚动哈希 <a class="header-anchor" href="#entry-rolling-hash-6f96b58019" aria-label="Permalink to &quot;滚动哈希 {#entry-rolling-hash-6f96b58019}&quot;">​</a></h3><p><span id="输出-5"></span><span id="示例-5"></span></p><p><span id="entry-rolling-hash-6f96b58019-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/strings/rolling-hash">滚动哈希</a>。</p><p>模哈希会碰撞，因此需要精确相等时必须二次比较原文；双哈希只能降低碰撞概率，不能证明相等。本页哈希算式使用 int，中间乘积要求 64 位 int；32 位目标应先改为 int64。</p><h3 id="entry-rabin-karp-38b7a1c919" tabindex="-1">Rabin–Karp <a class="header-anchor" href="#entry-rabin-karp-38b7a1c919" aria-label="Permalink to &quot;Rabin–Karp {#entry-rabin-karp-38b7a1c919}&quot;">​</a></h3><p><span id="输出-6"></span><span id="示例-6"></span></p><p><span id="entry-rabin-karp-38b7a1c919-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/strings/rabin-karp">Rabin–Karp</a>。</p><p>平均性能良好，但恶意碰撞可能让最坏时间退化。</p><h2 id="scene-encode-frequencies" tabindex="-1">按频率计算哈夫曼合并代价 <a class="header-anchor" href="#scene-encode-frequencies" aria-label="Permalink to &quot;按频率计算哈夫曼合并代价 {#scene-encode-frequencies}&quot;">​</a></h2><h3 id="entry-huffman-coding-15f81be490" tabindex="-1">哈夫曼编码 <a class="header-anchor" href="#entry-huffman-coding-15f81be490" aria-label="Permalink to &quot;哈夫曼编码 {#entry-huffman-coding-15f81be490}&quot;">​</a></h3><p><span id="输出-7"></span><span id="示例-7"></span></p><p><span id="entry-huffman-coding-15f81be490-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/strings/huffman-coding">哈夫曼编码</a>。</p><p>反复排序便于理解，使用最小堆可更高效。</p><h2 id="review-exercise" tabindex="-1">静态自检 <a class="header-anchor" href="#review-exercise" aria-label="Permalink to &quot;静态自检 {#review-exercise}&quot;">​</a></h2><p>预测 KMP(&quot;你好Go&quot;, &quot;Go&quot;) 与 KMP(&quot;你好Go&quot;, &quot;好&quot;) 的字节下标。提示：两个汉字分别占三个 UTF-8 字节，查找循环必须检查每个字节。</p><details class="details custom-block"><summary>参考解法</summary><p>分别为 6 和 3；若按 range string 只遍历码点起点，比较好字的首字节后会跳过其续字节而漏报。当前循环逐字节处理，匹配结果仍是字节下标。</p></details>',52)])])}const m=e(i,[["render",s]]);export{g as __pageData,m as default};
